SELECT sku, productName, flowType, packSize, caseWeightKg, unitsPerCase, costPriceInr, sellingPriceInr 
FROM store.products 
WHERE productName ILIKE '%atta%' OR packSize = '5 kg';

SELECT sku, name, pack, flow, case_kg, price_inr, cost_inr 
FROM store.products 
WHERE pack ILIKE '%5 kg%';
